CREATE TABLE expenses (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text NOT NULL REFERENCES stores(id), vendor text NOT NULL, category text NOT NULL, currency text NOT NULL CHECK(currency IN ('USD','EUR','GBP')), amount_minor bigint NOT NULL CHECK(amount_minor>0), recognized_date date NOT NULL, obligation_id text UNIQUE REFERENCES obligations(id), recognition text NOT NULL CHECK(recognition IN ('OPERATING','CAPITAL','COGS_LINKED','PERSONAL')), source text NOT NULL, notes text NOT NULL DEFAULT '', created_by text NOT NULL REFERENCES users(id));
ALTER TABLE recurring_expenses ADD COLUMN anchor_day integer;
ALTER TABLE obligations ADD COLUMN recurring_expense_id text REFERENCES recurring_expenses(id);
ALTER TABLE obligations ADD CONSTRAINT recurring_occurrence_unique UNIQUE(recurring_expense_id,due_at);
ALTER TABLE prepaid_cost_pools ADD COLUMN product_id text REFERENCES products(id);
ALTER TABLE prepaid_cost_pools ADD COLUMN component text NOT NULL DEFAULT 'packaging' CHECK(component IN ('product','packaging','fulfillment','shipping','other'));
ALTER TABLE prepaid_cost_pools ADD COLUMN name text NOT NULL DEFAULT 'Prepaid pool';
ALTER TABLE prepaid_cost_pools ADD COLUMN obligation_id text UNIQUE REFERENCES obligations(id);
ALTER TABLE prepaid_cost_pools ADD COLUMN source text NOT NULL DEFAULT 'MANUAL';
ALTER TABLE prepaid_cost_pools ADD CONSTRAINT prepaid_nonnegative CHECK(total_minor>0);
ALTER TABLE cost_reconciliations ADD COLUMN revision integer NOT NULL DEFAULT 1;
CREATE UNIQUE INDEX reconciliation_revision ON cost_reconciliations(order_cost_id,revision);
ALTER TABLE order_costs ADD COLUMN superseded_at timestamptz;
CREATE UNIQUE INDEX current_order_cost ON order_costs(order_item_id) WHERE superseded_at IS NULL;
ALTER TABLE refunds ADD COLUMN override_reason text;
CREATE UNIQUE INDEX refund_external_unique ON refunds(order_id,external_id) WHERE external_id IS NOT NULL;
ALTER TABLE orders ADD COLUMN customer_country text;
ALTER TABLE orders ADD COLUMN supplier_id text REFERENCES vendors(id);
ALTER TABLE orders ADD COLUMN supplier_batch text;
CREATE TABLE workspace_settings (store_id text NOT NULL REFERENCES stores(id), currency text NOT NULL, safety_buffer_minor bigint CHECK(safety_buffer_minor>=0), stock_watch_days integer NOT NULL DEFAULT 14 CHECK(stock_watch_days>0), stock_critical_days integer NOT NULL DEFAULT 3 CHECK(stock_critical_days>0), meta_watch_days integer NOT NULL DEFAULT 3 CHECK(meta_watch_days>0), freshness_hours integer NOT NULL DEFAULT 24 CHECK(freshness_hours>0), refund_policy text NOT NULL DEFAULT 'PLATFORM' CHECK(refund_policy IN ('PLATFORM','INTERNAL_REVIEWED')), PRIMARY KEY(store_id,currency));
CREATE TABLE payroll_runs (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text NOT NULL REFERENCES stores(id), employee text NOT NULL, period text NOT NULL, currency text NOT NULL, gross_minor bigint NOT NULL CHECK(gross_minor>=0), deductions_minor bigint NOT NULL CHECK(deductions_minor>=0), employer_minor bigint NOT NULL CHECK(employer_minor>=0), net_obligation_id text UNIQUE REFERENCES obligations(id), tax_obligation_id text UNIQUE REFERENCES obligations(id), created_by text NOT NULL REFERENCES users(id), CHECK(deductions_minor<=gross_minor));
CREATE TABLE owner_records (id text PRIMARY KEY, obligation_id text UNIQUE NOT NULL REFERENCES obligations(id), recipient text NOT NULL, classification text NOT NULL, declared_at date, withholding_minor bigint NOT NULL DEFAULT 0 CHECK(withholding_minor>=0), notes text NOT NULL DEFAULT '');
CREATE TABLE mapping_history (id text PRIMARY KEY, store_id text NOT NULL REFERENCES stores(id), legal_entity_id text NOT NULL REFERENCES legal_entities(id), effective_start date NOT NULL, effective_end date, evidence text NOT NULL, created_by text NOT NULL REFERENCES users(id), CHECK(effective_end IS NULL OR effective_end>effective_start));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['expenses','recurring_expenses','prepaid_cost_pools','prepaid_consumption','order_costs','cost_reconciliations','refunds','expected_inflows','meta_credit_snapshots','meta_payments','payroll_runs','owner_records','mapping_history'] LOOP EXECUTE format('CREATE TRIGGER operations_audit AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION audit_financial_change()',t); END LOOP; END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA company_os FROM PUBLIC;
